using System.Collections.Generic;
using UnityEngine;
using UnityEngine.SceneManagement;

/// <summary>
/// 单房间管理器 — 管理单个房间的运行时状态。
/// 负责怪物生成、门锁定/解锁、道具生成等。
/// </summary>
public class RoomManager : MonoBehaviour
{
    [Header("组件引用")]
    public RoomRoot roomRoot;

    [Header("货币掉落")]
    [SerializeField] private int _currencyPerEnemy = 3;
    [SerializeField] private Sprite _currencyIcon;

    [Header("房间状态")]
    [SerializeField] private bool _isCleared;
    private bool _isFirstEnter = true;

    /// <summary>房间是否已清完怪物</summary>
    public bool IsCleared => _isCleared;

    /// <summary>是否首次进入</summary>
    public bool IsFirstEnter => _isFirstEnter;

    /// <summary>获取指定位置的寻路网格（供敌人依赖注入）</summary>
    public PathfindingGrid GetGridAtPosition(Vector2 position)
    {
        if (roomRoot != null && roomRoot.PathGrid != null)
        {
            if (roomRoot.Bounds.Contains(position))
                return roomRoot.PathGrid;
        }
        return null;
    }

    /// <summary>当前存活怪物列表</summary>
    private List<GameObject> _aliveEnemies = new();

    /// <summary>所有门 Portal 引用</summary>
    private List<RoomPortal> _portals = new();

    public event System.Action OnRoomCleared;

    private void Awake()
    {
        if (roomRoot == null)
            roomRoot = GetComponent<RoomRoot>();

        // 自动加载货币图标
        if (_currencyIcon == null)
            _currencyIcon = Resources.Load<Sprite>("TestAssets/Icons/icon_atp");

        _portals.AddRange(GetComponentsInChildren<RoomPortal>());

        // 确保每次实例化都是首次进入状态 (防止序列化残留)
        _isFirstEnter = true;
        _isCleared = roomRoot.config.maxEnemies == 0? true : false;
    }

    /// <summary>玩家进入房间时调用</summary>
    public void OnPlayerEnter()
    {
        if (roomRoot == null) roomRoot = GetComponent<RoomRoot>();
        if (roomRoot == null || roomRoot.config == null) return;

        // BGM 切换：Boss 房间 → Boss 战音乐；其他房间 → 日常战斗音乐
        if (BgmManager.Instance != null)
        {
            if (roomRoot.config.roomType == RoomType.Boss)
                BgmManager.Instance.PlayBoss();
            else
                BgmManager.Instance.PlayCombat();
        }

        // Shop 房间特殊处理：开张商店
        if (roomRoot.config.roomType == RoomType.Shop)
        {
            if (_isFirstEnter)
            {
                _isFirstEnter = false;
                OpenShopRoom();
            }
            return;
        }

        Debug.Log($"[RoomManager] Room{roomRoot.roomId} OnPlayerEnter: _isFirstEnter={_isFirstEnter}, enemyPool={roomRoot.config.enemyPool?.Count}, minEnemies={roomRoot.config.minEnemies}");

        if (_isFirstEnter)
        {
            _isFirstEnter = false;

            // 统计：首次进入房间
            GameStatistics.Instance?.RecordRoomVisited(roomRoot.config.roomType);

            // 构建寻路网格（在敌人生成前）
            roomRoot.BuildPathfindingGrid();

            SpawnEnemies();
            Debug.Log($"[RoomManager] Room{roomRoot.roomId} spawned enemies, _aliveEnemies.Count={_aliveEnemies.Count}");

            if (_aliveEnemies.Count > 0)
            {
                Debug.Log($"[RoomManager] Room{roomRoot.roomId} calling LockDoors...");
                LockDoors();
                Debug.Log($"[RoomManager] Room{roomRoot.roomId} LockDoors done.");
            }
            else
            {
                // 无怪物的房间（如 Start 房）：直接生成道具（不生成血量回复物）
                var availablePoints = new List<Transform>();
                if (roomRoot.itemSpawnPoints != null)
                    availablePoints.AddRange(roomRoot.itemSpawnPoints);
                SpawnItems(availablePoints);
            }
        }
    }

    /// <summary>玩家离开房间时调用</summary>
    public void OnPlayerExit()
    {
        // 道具现在是普通 ItemPickup，离开后保留在地图中
    }

    /// <summary>锁定所有门 (启用阻挡物 + 禁用触发器)</summary>
    private void LockDoors()
    {
        foreach (var portal in _portals)
        {
            if (portal != null)
                portal.SetLocked(true);
        }
    }

    /// <summary>解锁所有门 (启用触发器 + 禁用阻挡物)，跳过隐藏墙</summary>
    private void UnlockDoors()
    {
        foreach (var portal in _portals)
        {
            if (portal != null && portal.HiddenWallHP <= 0)
                portal.SetLocked(false);
        }
    }

    /// <summary>生成怪物</summary>
    private void SpawnEnemies()
    {
        if (roomRoot == null || roomRoot.config == null) return;

        var cfg = roomRoot.config;

        // Boss 房在 hasBoss=false 时不生成敌人（空房间直接清场）
        if (cfg.roomType == RoomType.Boss)
        {
            var mapConfigAsset = MapManager.Instance?.MapConfigAsset;
            if (mapConfigAsset != null && !mapConfigAsset.hasBoss)
                return;
        }

        if (cfg.enemyPool == null || cfg.enemyPool.Count == 0) return;

        // 按权重选择敌人
        int totalEnemies = Random.Range(cfg.minEnemies, cfg.maxEnemies + 1);
        int spawnPointCount = roomRoot.enemySpawnPoints != null ? roomRoot.enemySpawnPoints.Length : 0;

        if (spawnPointCount == 0)
        {
            Debug.LogWarning($"Room {roomRoot.roomId}: 没有敌人生成点");
            return;
        }

        // 随机选取生成点 (不重复)
        var availablePoints = new List<int>();
        for (int i = 0; i < spawnPointCount; i++)
            availablePoints.Add(i);
        Shuffle(availablePoints);

        int spawnCount = Mathf.Min(totalEnemies, availablePoints.Count);

        for (int i = 0; i < spawnCount; i++)
        {
            // 按权重随机选择敌人类型
            var entry = PickWeighted(cfg.enemyPool);
            if (entry == null || entry.enemyPrefab == null) continue;

            var spawnPoint = roomRoot.enemySpawnPoints[availablePoints[i]];
            var enemy = Instantiate(entry.enemyPrefab, spawnPoint.position, Quaternion.identity, transform);
            _aliveEnemies.Add(enemy);

            // 监听敌人死亡，使用 IEnemy 接口
            if (enemy.TryGetComponent<IEnemy>(out var ienemy))
            {
                ienemy.OnDied += () => OnEnemyDied(enemy);
                ienemy.OnAssimilated += (_) => OnEnemyAssimilated(enemy);
            }
        }

        Debug.Log($"Room {roomRoot.roomId}: 生成了 {spawnCount} 个敌人");
    }

    /// <summary>按权重随机选择</summary>
    private EnemySpawnEntry PickWeighted(List<EnemySpawnEntry> entries)
    {
        float totalWeight = 0f;
        foreach (var e in entries) totalWeight += e.weight;

        if (totalWeight <= 0f) return entries.Count > 0 ? entries[0] : null;

        float roll = Random.Range(0f, totalWeight);
        float cumulative = 0f;
        foreach (var e in entries)
        {
            cumulative += e.weight;
            if (roll <= cumulative)
                return e;
        }
        return entries[^1];
    }

    /// <summary>敌人死亡回调</summary>
    private void OnEnemyDied(GameObject enemy)
    {
        RemoveAliveEnemy(enemy);

        // 生成货币掉落
        SpawnCurrency(enemy.transform.position, _currencyPerEnemy);

        if (_aliveEnemies.Count == 0)
        {
            OnAllEnemiesDefeated();
        }
    }

    /// <summary>敌人被同化为随从（不再计入房间清空判定）</summary>
    private void OnEnemyAssimilated(GameObject enemy)
    {
        RemoveAliveEnemy(enemy);

        if (_aliveEnemies.Count == 0)
        {
            OnAllEnemiesDefeated();
        }
    }

    /// <summary>
    /// 安全移除存活敌人 — List.Remove 依赖 EqualityComparer，Unity 对象销毁后
    /// ==重载返回 null 但比较器可能匹配失败，导致幽灵条目残留房间永远清不掉。
    /// 改用遍历 + Unity null 判断移除。
    /// </summary>
    private void RemoveAliveEnemy(GameObject enemy)
    {
        for (int i = _aliveEnemies.Count - 1; i >= 0; i--)
        {
            // 同时清理已销毁的幽灵条目
            if (_aliveEnemies[i] == null || _aliveEnemies[i] == enemy)
                _aliveEnemies.RemoveAt(i);
        }
    }

    /// <summary>
    /// 注册一个敌人到房间存活列表（亡语分裂/召唤生成的敌人也调用此方法），
    /// 否则亡语怪不计入 _aliveEnemies 会导致房间门提前开启。
    /// </summary>
    /// <summary>
    /// 注册一个敌人到房间存活列表（分裹/召唤生成的敌人也调用此方法）。
    /// 否则分裹不计入 _aliveEnemies 会导致房间门提前开启。
    /// </summary>
    public void RegisterEnemy(GameObject enemy)
    {
        if (enemy == null || _aliveEnemies.Contains(enemy)) return;

        _aliveEnemies.Add(enemy);

        if (enemy.TryGetComponent<IEnemy>(out var ienemy))
        {
            ienemy.OnDied += () => OnEnemyDied(enemy);
            ienemy.OnAssimilated += (_) => OnEnemyAssimilated(enemy);
        }
    }

    /// <summary>所有敌人被击败</summary>
    private void OnAllEnemiesDefeated()
    {
        _isCleared = true;

        // 解锁门
        UnlockDoors();
        // 激活相邻隐藏房的门 (变为可破坏状态)
        ActivateHiddenWalls();

        // 共享生成点列表：道具先生成占点，血量回复物后生成用剩余点
        var availablePoints = new List<Transform>();
        if (roomRoot.itemSpawnPoints != null)
            availablePoints.AddRange(roomRoot.itemSpawnPoints);

        // 道具先生成
        SpawnItems(availablePoints);

        // 血量回复物后生成（用剩余点）
        SpawnHealthPickups(availablePoints);

        // Boss/Exit 房生成下一层出口
        TrySpawnNextLevelExit();

        Debug.Log($"Room {roomRoot.roomId}: 已清空!");

        // 统计：清空房间
        GameStatistics.Instance?.RecordRoomCleared(roomRoot.config.roomType);

        OnRoomCleared?.Invoke();
    }

    /// <summary>Boss/Exit 房清空后在房间中心生成下一层出口</summary>
    private void TrySpawnNextLevelExit()
    {
        if (roomRoot == null || roomRoot.config == null) return;
        var roomType = roomRoot.config.roomType;
        if (roomType != RoomType.Boss) return;

        var mapConfigAsset = MapManager.Instance?.MapConfigAsset;
        if (mapConfigAsset == null) return;

        var exitGo = Instantiate(mapConfigAsset.nextLevelExitPrefab, roomRoot.Center, Quaternion.identity, transform);
        exitGo.name = "NextLevelExit";

        var exitComp = exitGo.GetComponent<NextLevelExit>();
        if (exitComp == null)
        {
            Debug.LogError("RoomManager: nextLevelExitPrefab 上没有挂载 NextLevelExit 组件，请在预制体上添加该脚本");
            return;
        }
        exitComp.nextSceneName = mapConfigAsset.nextSceneName;

        Debug.Log($"RoomManager: 房间 {roomRoot.roomId} 生成下一层出口 -> {mapConfigAsset.nextSceneName}");
    }

    /// <summary>激活通往相邻隐藏房的门</summary>
    private void ActivateHiddenWalls()
    {
        if (roomRoot == null) return;
        var graph = MapManager.Instance?.RoomGraph;
        if (graph == null) return;

        var node = graph.GetNode(roomRoot.roomId);
        if (node == null) return;

        foreach (var conn in node.connections)
        {
            var targetNode = graph.GetNode(conn.Key);
            if (targetNode == null || targetNode.roomType != RoomType.Hidden) continue;

            // 找到指向隐藏房的门 Portal
            var portals = GetComponentsInChildren<RoomPortal>(true);
            foreach (var portal in portals)
            {
                if (portal.targetRoomId == conn.Key && portal.HiddenWallHP > 0)
                {
                    portal.SetBreakable();
                    break;
                }
            }
        }
    }

    /// <summary>生成道具（概率+权重，占点后从 availablePoints 移除）</summary>
    private void SpawnItems(List<Transform> availablePoints)
    {
        if (roomRoot == null || roomRoot.config == null) return;
        var cfg = roomRoot.config;

        if (availablePoints == null || availablePoints.Count == 0) return;

        // 概率判定
        if (Random.value > cfg.itemSpawnChance) return;

        // 权重抽取生成数量
        int count = GetWeightedRandomCount(cfg.itemCountWeights);
        count = Mathf.Min(count, availablePoints.Count);
        if (count <= 0) return;

        var library = ItemsLibrary.Instance;
        if (library == null)
        {
            Debug.LogWarning("[RoomManager] ItemsLibrary 未找到，跳过道具生成");
            return;
        }

        var pool = (cfg.itemPool != null && cfg.itemPool.Count > 0) ? cfg.itemPool : null;
        var weights = (cfg.qualityWeights != null && cfg.qualityWeights.Length > 0) ? cfg.qualityWeights : null;
        var filter = ItemPoolFilter.GetPlayerItemManager();

        var picked = library.GetRandomItemPrefabs(count, pool, weights, filter);
        for (int i = 0; i < picked.Count && availablePoints.Count > 0; i++)
        {
            if (picked[i] == null) continue;
            int idx = Random.Range(0, availablePoints.Count);
            Instantiate(picked[i], availablePoints[idx].position, Quaternion.identity, transform);
            availablePoints.RemoveAt(idx);
        }

        // Boss 房必定生成一个溶酶体（使用无副作用方法，不影响随机池）
        if (roomRoot.config.roomType == RoomType.Boss)
        {
            var lysosomePrefab = library.GetItemPrefabDirectly("lysosome");
            if (lysosomePrefab != null && availablePoints.Count > 0)
            {
                int idx = Random.Range(0, availablePoints.Count);
                Instantiate(lysosomePrefab, availablePoints[idx].position, Quaternion.identity, transform);
                availablePoints.RemoveAt(idx);
            }
        }
    }

    /// <summary>生成血量回复物（清房后概率+权重，用道具剩余的生成点）</summary>
    private void SpawnHealthPickups(List<Transform> availablePoints)
    {
        if (roomRoot == null || roomRoot.config == null) return;
        var cfg = roomRoot.config;

        if (availablePoints == null || availablePoints.Count == 0) return;
        if (cfg.healthPickupPrefab == null) return;

        // 概率判定
        if (Random.value > cfg.healthPickupChance) return;

        // 权重抽取生成数量
        int count = GetWeightedRandomCount(cfg.healthPickupCountWeights);
        count = Mathf.Min(count, availablePoints.Count);
        if (count <= 0) return;

        for (int i = 0; i < count; i++)
        {
            if (availablePoints.Count == 0) break;
            int idx = Random.Range(0, availablePoints.Count);
            Instantiate(cfg.healthPickupPrefab, availablePoints[idx].position, Quaternion.identity, transform);
            availablePoints.RemoveAt(idx);
        }
    }

    /// <summary>加权随机抽取生成数量（索引i → 生成i+1个）</summary>
    private int GetWeightedRandomCount(int[] weights)
    {
        if (weights == null || weights.Length == 0) return 0;
        int totalWeight = 0;
        foreach (int w in weights) totalWeight += w;
        if (totalWeight <= 0) return 0;
        int roll = Random.Range(0, totalWeight);
        int cumulative = 0;
        for (int i = 0; i < weights.Length; i++)
        {
            cumulative += weights[i];
            if (roll < cumulative) return i + 1;
        }
        return weights.Length;
    }

    /// <summary>协程: 轮询检查敌人死亡 (用于未继承 BaseEnemy 的敌人)</summary>
    private System.Collections.IEnumerator WatchEnemyDeath(GameObject enemy)
    {
        while (enemy != null)
        {
            yield return new WaitForSeconds(0.5f);
        }
        OnEnemyDied(null);
    }

    private static void Shuffle<T>(List<T> list)
    {
        for (int i = list.Count - 1; i > 0; i--)
        {
            int j = Random.Range(0, i + 1);
            (list[i], list[j]) = (list[j], list[i]);
        }
    }

    // ==================== Shop 房间 ====================

    /// <summary>开张商店</summary>
    private void OpenShopRoom()
    {
        var shopManager = GetComponent<ShopManager>();
        if (shopManager == null)
        {
            Debug.LogWarning($"[RoomManager] Room{roomRoot.roomId}: Shop 房间但未挂载 ShopManager 组件");
            return;
        }

        shopManager.OpenShop();
    }

    /// <summary>打烊商店</summary>
    private void CloseShopRoom()
    {
        var shopManager = GetComponent<ShopManager>();
        if (shopManager != null)
            shopManager.CloseShop();
    }

    /// <summary>在指定位置生成货币掉落物</summary>
    private void SpawnCurrency(Vector3 position, int amount)
    {
        var go = new GameObject("CurrencyPickup", typeof(SpriteRenderer), typeof(CircleCollider2D), typeof(CurrencyPickup));

        var sr = go.GetComponent<SpriteRenderer>();
        sr.sprite = _currencyIcon;
        sr.sortingOrder = 5;

        var col = go.GetComponent<CircleCollider2D>();
        col.isTrigger = true;
        col.radius = 0.4f;

        var pickup = go.GetComponent<CurrencyPickup>();
        pickup.amount = amount;

        // 随机散布
        position += (Vector3)(Random.insideUnitCircle * 0.5f);
        go.transform.position = position;
        go.transform.SetParent(transform);
    }
}

using System;
using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// 敌人聚合门面：实现 IEnemy / IDamageable / ISkillCaster，自动收集子组件并负责连线。
/// 碰撞伤害直接在此处理（OnTriggerStay2D + OnCollisionStay2D）。
/// 所有数值属性来源：EnemyStats（类似 PlayerStats 的单一数据源）。
/// </summary>
[DisallowMultipleComponent]
public class EnemyCore : MonoBehaviour, IEnemy
{
    [Header("配置")]
    public EnemyConfig config;

    [Header("动画（可选，留空则从 config displayName 自动查找）")]
    [Tooltip("AnimatorController 资产路径（Assets/ 开始），留空则按敌人名自动查找")]
    [SerializeField] private string _animatorControllerPath = "";

    // 子组件
    public EnemyStats Health { get; private set; }
    public EnemyMovement Movement { get; private set; }
    public EnemySkillManager SkillManager { get; private set; }
    public EnemyStateMachine StateMachine { get; private set; }

    // 缓存玩家引用 + 最后已知位置（供状态机读取）
    public Transform PlayerTarget { get; set; }
    public Vector2 LastKnownPlayerPosition { get; set; }

    public Transform EnemyTransform => transform;
    public bool IsDead => Health != null && Health.IsDead;
    public bool IsAssimilated { get; private set; }
    public IReadOnlyList<SkillInstance> SkillInstances =>
        SkillManager != null ? SkillManager.SkillInstances : new List<SkillInstance>();
    public event Action OnDied;
    public event Action<IEnemy> OnAssimilated;

    /// <summary>全局静态事件 — 任意敌人死亡时触发 (EnemyCore)</summary>
    public static event Action<EnemyCore> OnAnyEnemyDied;

    /// <summary>全局静态事件 — 任意敌人生成时触发 (EnemyCore)</summary>
    public static event Action<EnemyCore> OnAnyEnemySpawned;

    /// <summary>全局静态事件 — 任意敌人接触伤害命中时触发 (enemy, hitTarget)</summary>
    public static event Action<EnemyCore, GameObject> OnAnyContactHit;

    /// <summary>玩家碰撞伤害减免乘区（细胞骨架），1=正常，0.7=减免30%</summary>
    public static float PlayerCollisionReductionFactor = 1f;

    // 碰撞伤害冷却
    private float _lastContactDamageTime = -10f;
    private Animator _animator;
    private SpriteRenderer _spriteRenderer;

    private void Awake()
    {
        Health       = GetComponent<EnemyStats>();
        Movement     = GetComponent<EnemyMovement>();
        SkillManager = GetComponent<EnemySkillManager>();
        StateMachine = GetComponent<EnemyStateMachine>();

        if (Health       == null) Health       = gameObject.AddComponent<EnemyStats>();
        if (Movement     == null) Movement     = gameObject.AddComponent<EnemyMovement>();
        if (SkillManager == null) SkillManager = gameObject.AddComponent<EnemySkillManager>();
        if (StateMachine == null) StateMachine = gameObject.AddComponent<EnemyStateMachine>();

        _animator = GetComponent<Animator>();
        _spriteRenderer = GetComponent<SpriteRenderer>();

        // 运行时 fallback：若 Animator 缺少 controller，按敌人名自动加载
        if (_animator != null && _animator.runtimeAnimatorController == null && config != null)
        {
            string enemyName = config.displayName;
            string autoPath = "Assets/Animations/Enemy/" + enemyName + "/" + enemyName + "_Controller.controller";
#if UNITY_EDITOR
            var ctrl = UnityEditor.AssetDatabase.LoadAssetAtPath<RuntimeAnimatorController>(autoPath);
            if (ctrl != null)
            {
                _animator.runtimeAnimatorController = ctrl;
            }
            else
            {
                Debug.LogWarning("[EnemyCore] AnimatorController not found at: " + autoPath);
            }
#else
            // 非 Editor 环境需将 controller 放入 Resources 文件夹
            var ctrl = Resources.Load<RuntimeAnimatorController>(enemyName + "_Controller");
            if (ctrl != null)
                _animator.runtimeAnimatorController = ctrl;
#endif
        }

        // 技能释放 → 触发释放动画
        if (SkillManager != null)
        {
            SkillManager.OnSkillCast += (_, _) =>
            {
                if (_animator != null && HasAnimatorParameter("IsCasting"))
                {
                    _animator.SetBool("IsCasting", true);
                    StartCoroutine(ResetCastBool(1.4f));
                }
            };
        }

        // ═══ 单一数据源：EnemyConfig → EnemyStats（全部属性） ═══
        if (config != null)
        {
            if (Health != null)
            {
                Health.MaxHealth             = config.maxHealth;
                Health.PatrolSpeed           = config.patrolSpeed;
                Health.ChaseSpeed            = config.chaseSpeed;
                Health.DetectionRange        = config.detectionRange;
                Health.AttackRange           = config.attackRange;
                Health.ContactDamage         = config.contactDamage;
                Health.ContactDamageCooldown = config.contactDamageCooldown;
                Health.Initialize();
            }

            if (SkillManager != null)
            {
                // 固定技能列表优先：按 ID 精确装配；否则从技能库随机抽取
                if (config.fixedSkillIds != null && config.fixedSkillIds.Count > 0)
                    SkillManager.LoadSkills(config.skillLibrary, config.fixedSkillIds.ToArray());
                else
                    SkillManager.InitializeFromLibrary(config.skillLibrary);

                // 被动技能（永久光环等）在装配后自动执行一次
                SkillManager.AutoCastPassives(this);
            }
        }
        else if (Health != null)
        {
            Health.Initialize();
        }

        // 绑定死亡事件
        if (Health != null)
        {
            Health.OnDied += () =>
            {
                OnDied?.Invoke();
                OnAnyEnemyDied?.Invoke(this);
                if (StateMachine != null)
                    StateMachine.ChangeState(new DeadState(this));
            };
        }

        // 依赖注入：获取当前房间的寻路网格
        if (Movement != null)
        {
            var roomMgr = FindObjectOfType<RoomManager>();
            if (roomMgr != null)
            {
                var grid = roomMgr.GetGridAtPosition(transform.position);
                if (grid != null)
                    Movement.SetRoomGrid(grid);
            }
        }

        // 广播生成事件
        OnAnyEnemySpawned?.Invoke(this);
    }

    private void Start()
    {
        StartCoroutine(TargetRefreshRoutine());

        // 启动默认状态
        if (StateMachine != null)
        {
            if (config != null && config.patrolPoints != null && config.patrolPoints.Count > 0)
                StateMachine.ChangeState(new PatrolState(this));
            else
                StateMachine.ChangeState(new IdleState(this));
        }
    }

    /// <summary>
    /// 周期性动态索敌：初始查找玩家后，每 0.3s 扫描检测范围内最近的 "Player" 标签目标（含随从）。
    /// 死亡或同化后自动停止。
    /// </summary>
    private System.Collections.IEnumerator TargetRefreshRoutine()
    {
        // Phase 1: 初始查找（同原 LazyFindPlayer 逻辑）
        while (PlayerTarget == null)
        {
            if (PlayerManager.Instance != null && PlayerManager.Instance.CurrentPlayer != null)
                PlayerTarget = PlayerManager.Instance.CurrentPlayer.transform;
            else
                PlayerTarget = GameObject.FindGameObjectWithTag("Player")?.transform;

            yield return new WaitForSeconds(0.3f);
        }

        // Phase 2: 周期性动态刷新 — 扫描最近的 "Player" 标签目标（含随从）
        while (true)
        {
            yield return new WaitForSeconds(0.3f);
            if (IsDead || IsAssimilated) yield break;

            Transform nearest = FindNearestPlayerTarget();
            if (nearest != null)
                PlayerTarget = nearest;
        }
    }

    /// <summary>
    /// 在检测范围内查找最近的 "Player" 标签目标（含真实玩家和随从）。
    /// 死亡随从的 Collider 已禁用，OverlapCircleAll 自然跳过。
    /// </summary>
    private Transform FindNearestPlayerTarget()
    {
        if (Health == null) return null;

        Vector2 center = transform.position;
        float range = Health.DetectionRange;

        Collider2D[] hits = Physics2D.OverlapCircleAll(center, range);
        Transform best = null;
        float minDist = float.MaxValue;

        foreach (var hit in hits)
        {
            if (!hit.CompareTag("Player")) continue;
            if (hit.transform == transform) continue;

            // 跳过死亡的敌人/随从（Collider 已禁用，此为双保险）
            var core = hit.GetComponent<EnemyCore>();
            if (core != null && core.IsDead) continue;

            float d = ((Vector2)hit.transform.position - center).sqrMagnitude;
            if (d < minDist)
            {
                minDist = d;
                best = hit.transform;
            }
        }

        return best;
    }

    private System.Collections.IEnumerator ResetCastBool(float delay)
    {
        yield return new WaitForSeconds(delay);
        if (_animator != null && HasAnimatorParameter("IsCasting"))
            _animator.SetBool("IsCasting", false);
    }

    /// <summary>检查 Animator 是否包含指定参数（避免 SetBool 报 "Parameter does not exist"）</summary>
    private bool HasAnimatorParameter(string paramName)
    {
        if (_animator == null || _animator.parameters == null) return false;
        foreach (var p in _animator.parameters)
            if (p.name == paramName) return true;
        return false;
    }

    // ---------- 朝向 ----------
    private void LateUpdate()
    {
        if (IsDead || _spriteRenderer == null || PlayerTarget == null) return;

        // 施法期间也允许翻转，始终跟随玩家方向
        float dx = PlayerTarget.position.x - transform.position.x;
        if (Mathf.Abs(dx) > 0.1f)
            _spriteRenderer.flipX = dx < 0f;
    }

    // ---------- 碰撞伤害 ----------

    private void OnTriggerStay2D(Collider2D other)
    {
        ProcessContactDamage(other.gameObject);
    }

    private void OnCollisionStay2D(Collision2D collision)
    {
        ProcessContactDamage(collision.gameObject);
    }

    private void ProcessContactDamage(GameObject other)
    {
        if (IsDead || Health == null) return;

        string targetTag = IsAssimilated ? "Enemy" : "Player";
        if (!other.CompareTag(targetTag)) return;

        if (Time.time < _lastContactDamageTime + Health.ContactDamageCooldown) return;

        // 护盾拦截
        var shield = other.GetComponent<KeratinShieldRuntime>();
        if (shield != null && shield.IsActive)
        {
            shield.TryBlock();
            _lastContactDamageTime = Time.time;
            return;
        }

        // 碰撞免疫
        var playerStats = other.GetComponent<PlayerStats>();
        if (playerStats != null && playerStats.ImmuneToContactDamage) return;

        float dmg = Health.ContactDamage;

        // 细胞骨架：非随从（敌人）对玩家的碰撞伤害减免
        if (!IsAssimilated && PlayerCollisionReductionFactor < 1f)
            dmg *= PlayerCollisionReductionFactor;

        // 干扰素：随从攻击命中时给目标减速
        if (IsAssimilated && EnemyFollower.ApplySlow && other.CompareTag("Enemy"))
        {
            var slow = other.GetComponent<SlowEffect>();
            if (slow == null)
                slow = other.AddComponent<SlowEffect>();
            slow.Apply(EnemyFollower.SlowFactor, EnemyFollower.SlowDuration);
        }

        var damageable = other.GetComponent<IDamageable>();
        if (damageable != null)
        {
            damageable.TakeDamage(dmg);
            _lastContactDamageTime = Time.time;

            // 广播接触命中事件（供 OnContactHitBuff 等效果使用）
            OnAnyContactHit?.Invoke(this, other.gameObject);
        }
    }

    // ---------- IDamageable (门面) ----------
    public void TakeDamage(float damage)
    {
        if (Health != null)
            Health.TakeDamage(damage);
    }

    // ---------- ISkillCaster ----------
    public Transform CasterTransform => transform;

    public Vector2 GetTargetDirection()
    {
        if (PlayerTarget == null) return Vector2.down;
        return (PlayerTarget.position - transform.position).normalized;
    }

    public float GetAttackStrength()
    {
        return Health != null ? Health.ContactDamage : 10f;
    }

    public Projectile.OwnerType GetOwnerType() =>
        IsAssimilated ? Projectile.OwnerType.Player : Projectile.OwnerType.Enemy;

    public float GetSkillDamageModifier() => 1f;

    // ---------- 同化 ----------
    /// <summary>同化敌人为随从（自动分配槽位）</summary>
    public void Assimilate(Transform playerTarget)
    {
        Assimilate(playerTarget, -1);
    }

    /// <summary>
    /// 同化敌人为随从，并指定随从槽位索引（-1=自动分配）。
    /// </summary>
    public void Assimilate(Transform playerTarget, int slotIndex)
    {
        IsAssimilated = true;

        if (Health != null)
            Health.ClearOnDied();

        OnAssimilated?.Invoke(this);

        gameObject.tag = "Player";

        if (StateMachine != null)
        {
            StateMachine.ChangeState(null);
            StateMachine.enabled = false;
        }

        Movement?.Stop();

        EnemyFollower follower = GetComponent<EnemyFollower>();
        if (follower == null)
            follower = gameObject.AddComponent<EnemyFollower>();
        follower.Activate(playerTarget, slotIndex);

        PlayerTarget = playerTarget;
    }

    /// <summary>
    /// 以"已同化"方式消耗敌人（同种升级场景）：触发 OnAssimilated 供房间计数，
    /// 但不创建随从，直接销毁该敌人。
    /// </summary>
    public void ConsumeAsAssimilated(Transform playerTarget)
    {
        IsAssimilated = true;

        if (Health != null)
            Health.ClearOnDied();

        OnAssimilated?.Invoke(this);

        gameObject.tag = "Player";

        if (StateMachine != null)
        {
            StateMachine.ChangeState(null);
            StateMachine.enabled = false;
        }

        Movement?.Stop();

        PlayerTarget = playerTarget;
        Destroy(gameObject);
    }
}

using UnityEngine;

/// <summary>
/// 房间门 — 挂载在每个门 GO 上。
/// 普通门：Update 中基于距离+输入方向检测玩家是否朝门移动 → 切换房间。
/// 隐藏墙：清房后 openTrigger 启用接收子弹，命中 N 次后墙壁破碎，显示门。
/// 无连接的门：直接隐藏，不出现墙壁贴图。
/// </summary>
public class RoomPortal : MonoBehaviour
{
    [Header("门配置")]
    public DoorDirection direction;
    public int targetRoomId = -1;

    [Header("组件引用")]
    [Tooltip("门 GO 的 SpriteRenderer")]
    public SpriteRenderer doorSprite;

    [Tooltip("开门/子弹检测的 Trigger Collider")]
    public Collider2D openTrigger;

    [Tooltip("关门/隐藏墙时激活的阻挡物")]
    public GameObject doorBlocker;

    [Header("触发设置")]
    public string targetTag = "Player";

    private bool _locked;
    private bool _hidden;       // 无连接，永久隐藏
    private bool _breakable;
    private int _hiddenWallHP;
    private int _currentHP;

    // 惰性缓存的玩家引用 (零 Find, 零 GC)
    private static PlayerController _cachedPlayer;

    private void Awake()
    {
        if (doorSprite == null) doorSprite = GetComponent<SpriteRenderer>();
        if (openTrigger == null) openTrigger = GetComponent<Collider2D>();
        if (openTrigger != null) openTrigger.isTrigger = true;
    }

    private void Update()
    {
        if (_hidden || _locked || targetRoomId < 0) return;
        if (_breakable) return;
        if (MapManager.Instance == null) return;
        if (MapManager.Instance.IsSwitchingRoom) return;
        if (!MapManager.Instance.CanTriggerPortal()) return;

        // 惰性缓存 PlayerController
        if (_cachedPlayer == null || _cachedPlayer.gameObject == null)
        {
            var player = PlayerManager.Instance?.CurrentPlayer;
            if (player == null) return;
            _cachedPlayer = player.GetComponent<PlayerController>();
            if (_cachedPlayer == null) return;
        }

        Vector2 playerPos = _cachedPlayer.transform.position;
        Vector2 doorPos = transform.position;
        Vector2 inputDir = _cachedPlayer.MoveDirection;

        float dx = Mathf.Abs(playerPos.x - doorPos.x);
        float dy = Mathf.Abs(playerPos.y - doorPos.y);

        float thresholdY = MapManager.Instance.PortalEnterThresholdY;
        float thresholdX = MapManager.Instance.PortalEnterThresholdX;
        float minInput = MapManager.Instance.PortalMinInput;

        bool inRange, movingTowardDoor;
        switch (direction)
        {
            case DoorDirection.Top:
                inRange = dy < thresholdY && dx < thresholdX;
                movingTowardDoor = inputDir.y > minInput;
                break;
            case DoorDirection.Bottom:
                inRange = dy < thresholdY && dx < thresholdX;
                movingTowardDoor = inputDir.y < -minInput;
                break;
            case DoorDirection.Left:
                inRange = dx < thresholdY && dy < thresholdX;
                movingTowardDoor = inputDir.x < -minInput;
                break;
            case DoorDirection.Right:
                inRange = dx < thresholdY && dy < thresholdX;
                movingTowardDoor = inputDir.x > minInput;
                break;
            default: return;
        }

        if (inRange && movingTowardDoor)
        {
            MapManager.Instance.OnPortalTriggered();
            MapManager.Instance.SwitchRoom(targetRoomId, direction);
        }
    }

    private void OnTriggerEnter2D(Collider2D other)
    {
        // 可破坏墙壁：检测子弹
        if (_breakable && other.TryGetComponent<Projectile>(out var proj))
        {
            OnBulletHit(proj);
            return;
        }
    }

    private void OnBulletHit(Projectile proj)
    {
        _currentHP--;
        Destroy(proj.gameObject);

        if (_currentHP <= 0)
            BreakWall();
    }

    private void BreakWall()
    {
        _breakable = false;
        _hiddenWallHP = 0;
        _locked = false;

        // 隐藏墙破坏后显示门
        if (doorBlocker != null) doorBlocker.SetActive(false);
        if (doorSprite != null) doorSprite.enabled = true;
        if (openTrigger != null) openTrigger.enabled = true;

        Debug.Log($"RoomPortal: 隐藏墙已破坏, 门已显示 (方向: {direction})");
    }

    /// <summary>设置为隐藏墙</summary>
    public void SetAsBreakableWall(int hp)
    {
        if (hp <= 0) return;
        _hiddenWallHP = hp;
        _currentHP = hp;
        _breakable = false;
        _locked = true;

        if (doorSprite != null) doorSprite.enabled = false;
        if (openTrigger != null) openTrigger.enabled = false;
        if (doorBlocker != null) doorBlocker.SetActive(true);
    }

    /// <summary>激活可破坏状态（清房后调用）：启用 openTrigger 接收子弹</summary>
    public void SetBreakable()
    {
        if (_hiddenWallHP <= 0 || _breakable) return;
        _breakable = true;
        if (openTrigger != null) openTrigger.enabled = true;
        Debug.Log($"RoomPortal: 隐藏墙可破坏 (方向: {direction}, HP: {_currentHP})");
    }

    public bool IsBreakable => _breakable;
    public int HiddenWallHP => _hiddenWallHP;

    /// <summary>锁定/解锁门</summary>
    public void SetLocked(bool locked)
    {
        if (_hidden) return;
        _locked = locked;

        if (openTrigger != null)
            openTrigger.enabled = !locked;

        if (doorSprite != null)
            doorSprite.enabled = !locked;

        if (doorBlocker != null)
            doorBlocker.SetActive(locked);
    }

    /// <summary>永久隐藏门（无连接房间），不显示墙壁贴图</summary>
    public void HideAsWall()
    {
        targetRoomId = -1;
        _hidden = true;
        _breakable = false;
        _hiddenWallHP = 0;

        if (openTrigger != null) openTrigger.enabled = false;
        if (doorSprite != null) doorSprite.enabled = false;
        if (doorBlocker != null) doorBlocker.SetActive(false);
    }
}

using UnityEngine;
using UnityEngine.SceneManagement;
using System.Collections;

/// <summary>
/// 随从行为组件：接管被同化敌人的 AI。
/// AI 决策由 FollowerStateMachine 驱动（Idle/Follow/Chase/Attack 四状态）。
/// 生命周期管理（传送/复活/跨场景/进化buff/道具增强）保留在本组件中。
/// 由 EnemyCore.Assimilate() 激活。
/// </summary>
[RequireComponent(typeof(EnemyCore))]
public class EnemyFollower : MonoBehaviour
{
    [Header("随从参数")]
    [SerializeField] private float _followDistance = 3.5f;
    [SerializeField] private float _detectionRange = 8f;
    [SerializeField] private float _attackRange = 2f;
    [SerializeField] private float _followSpeed = 3f;
    [Tooltip("离玩家超过此距离时直接传送到身边，防止掉队")]
    [SerializeField] private float _maxTeleportDistance = 15f;

    [Header("同种升级")]
    [Tooltip("同种类随从升级：每级属性倍率增量（0.15 = 每级 +15%）")]
    [SerializeField] private float _levelStatFactor = 0.15f;
    [Tooltip("同种类随从升级：技能等级是否 +1")]
    [SerializeField] private bool _upgradeSkillsOnLevelUp = true;

    [Header("复活")]
    [Tooltip("死亡后复活延迟（秒）")]
    [SerializeField] private float _respawnDelay = 10f;

    private Transform _player;
    private EnemyCore _core;
    private EnemyMovement _movement;
    private EnemySkillManager _skillManager;
    private bool _isActive;
    private bool _isReviving;
    private bool _isPaused;
    private FollowerStateMachine _followerSM;

    // 进化倾向 buff：记录原始属性，动态刷新时从原始值重算
    private float _origMaxHealth, _origPatrolSpeed, _origChaseSpeed;
    private float _origDetectionRange, _origAttackRange, _origContactDamage, _origContactDamageCooldown;

    /// <summary>所有活跃随从列表（供 MapManager 查询，避免 FindObjectsByType）</summary>
    public static readonly System.Collections.Generic.List<EnemyFollower> ActiveFollowers = new();

    /// <summary>随从列表修订号：增删/升级时自增，UI 据此重建行</summary>
    public static int Revision { get; private set; }

    /// <summary>随从槽位索引（0..MaxFollowerCount-1，-1=未分配）</summary>
    public int SlotIndex { get; private set; } = -1;

    /// <summary>随从等级（同种升级叠加，默认 1）</summary>
    public int Level { get; private set; } = 1;

    // ── 道具增强（静态，影响所有随从）──
    /// <summary>随从生命上限乘区（免疫球蛋白）</summary>
    public static float MaxHealthMultiplier = 1f;
    /// <summary>随从伤害乘区（集落刺激因子 CSF）</summary>
    public static float DamageMultiplier = 1f;
    /// <summary>随从技能冷却乘区（白细胞介素-2 IL-2）</summary>
    public static float FollowerCooldownFactor = 1f;
    /// <summary>随从攻击是否附带减速（干扰素）</summary>
    public static bool ApplySlow = false;
    /// <summary>减速比例（干扰素），0.8 = 减速20%</summary>
    public static float SlowFactor = 0.8f;
    /// <summary>减速持续时间（秒）</summary>
    public static float SlowDuration = 2f;
    /// <summary>随从数量上限（胸腺肽），默认4</summary>
    public static int MaxFollowerCount = 4;

    // ── 暴露给状态机的只读属性 ──
    public EnemyCore Core => _core;
    public EnemyMovement Movement => _movement;
    public EnemySkillManager SkillManager => _skillManager;
    public Transform Player => _player;
    public FollowerStateMachine StateMachine => _followerSM;
    public float FollowDistance => _followDistance;
    public float DetectionRange => _detectionRange;
    public float AttackRange => _attackRange;
    public float FollowSpeed => _followSpeed;

    /// <summary>随从是否处于活跃状态（未被暂停）</summary>
    public bool IsActive => _isActive && !_isPaused;

    /// <summary>暂停/恢复随从 AI（不改变 _isActive，用于陷阱等临时暂停）</summary>
    public void SetPaused(bool paused)
    {
        _isPaused = paused;
        if (paused) _movement?.Stop();
    }

    private void OnEnable()
    {
        ActiveFollowers.Add(this);
        Revision++;

        if (MapManager.Instance != null)
            MapManager.Instance.OnRoomSwitchStarted += OnRoomSwitchStarted;
        SceneManager.sceneLoaded += OnSceneLoaded;
    }

    private void OnDisable()
    {
        ActiveFollowers.Remove(this);
        Revision++;
        if (_core != null && _core.Health != null)
            _core.Health.OnDied -= HandleDeath;
        if (MapManager.Instance != null)
            MapManager.Instance.OnRoomSwitchStarted -= OnRoomSwitchStarted;
        SceneManager.sceneLoaded -= OnSceneLoaded;
    }

    private void Awake()
    {
        _core = GetComponent<EnemyCore>();
    }

    /// <summary>
    /// 激活随从模式。
    /// </summary>
    /// <param name="player">玩家 Transform</param>
    /// <param name="slotIndex">槽位索引（-1=自动分配最小空闲槽）</param>
    public void Activate(Transform player, int slotIndex = -1)
    {
        _player = player;
        _isActive = true;

        // 槽位分配：显式指定或自动取最小空闲槽
        SlotIndex = slotIndex >= 0 ? slotIndex : FindFreeSlotIndex();

        _movement = _core.Movement;
        _skillManager = _core.SkillManager;

        // 记录原始属性，用于进化倾向 buff 重算
        if (_core.Health != null)
        {
            _origMaxHealth = _core.Health.MaxHealth;
            _origPatrolSpeed = _core.Health.PatrolSpeed;
            _origChaseSpeed = _core.Health.ChaseSpeed;
            _origDetectionRange = _core.Health.DetectionRange;
            _origAttackRange = _core.Health.AttackRange;
            _origContactDamage = _core.Health.ContactDamage;
            _origContactDamageCooldown = _core.Health.ContactDamageCooldown;

            // 应用当前进化倾向 buff
            ApplyEvolutionBuff();

            _core.Health.OnDied += HandleDeath;
        }

        // 先脱离房间父节点，再标记 DontDestroyOnLoad（对有父节点的子对象直接调用不生效）
        transform.SetParent(null);
        DontDestroyOnLoad(gameObject);

        // 创建随从状态机并启动
        _followerSM = new FollowerStateMachine();
        _followerSM.ChangeState(new FollowerIdleState(this));
    }

    /// <summary>根据玩家进化倾向刷新随从全属性增幅（叠加道具乘区）</summary>
    public void ApplyEvolutionBuff()
    {
        if (_core?.Health == null || !_isActive) return;

        var playerStats = _player?.GetComponent<PlayerStats>();
        if (playerStats == null) return;

        float tendency = playerStats.EvolutionTendency;
        float factor = playerStats.EvolveFollowerBuffFactor;
        float levelMult = 1f + (Level - 1) * _levelStatFactor;
        float mult = Mathf.Max(0f, 1f + (-tendency) * factor) * levelMult;

        _core.Health.MaxHealth = Mathf.Max(_origMaxHealth * mult * MaxHealthMultiplier, 1f);
        _core.Health.PatrolSpeed = _origPatrolSpeed * mult;
        _core.Health.ChaseSpeed = _origChaseSpeed * mult;
        _core.Health.DetectionRange = _origDetectionRange * mult;
        _core.Health.AttackRange = _origAttackRange * mult;
        _core.Health.ContactDamage = _origContactDamage * mult * DamageMultiplier;
        _core.Health.ContactDamageCooldown = _origContactDamageCooldown * mult;

        // 应用随从技能冷却乘区
        if (_skillManager != null)
        {
            foreach (var s in _skillManager.SkillInstances)
                s.CooldownFactor = FollowerCooldownFactor;
        }
    }

    /// <summary>刷新所有活跃随从的进化倾向 buff（由 PlayerStats 在倾向值变化时调用）</summary>
    public static void RefreshAllFollowers(float tendency, float factor)
    {
        foreach (var f in ActiveFollowers)
            f.ApplyEvolutionBuff();
    }

    /// <summary>刷新所有活跃随从（道具增强变化时调用）</summary>
    public static void RefreshAllFollowers()
    {
        foreach (var f in ActiveFollowers)
            f.ApplyEvolutionBuff();
    }

    private void Update()
    {
        if (!_isActive || _isPaused || _player == null) return;
        if (_core.Health != null && _core.Health.IsDead) return;

        // 离玩家过远 → 直接传送到身边，防止掉队或被卡住
        float sqrDistToPlayer = ((Vector2)transform.position - (Vector2)_player.position).sqrMagnitude;
        if (sqrDistToPlayer > _maxTeleportDistance * _maxTeleportDistance)
        {
            _movement?.Teleport(_player.position);
            return;
        }

        _followerSM?.Tick();
    }

    /// <summary>在检测范围内查找最近的 "Enemy" 标签目标</summary>
    public Transform FindNearestEnemy(Vector2 center)
    {
        Collider2D[] hits = Physics2D.OverlapCircleAll(center, _detectionRange);
        Transform nearest = null;
        float minDist = float.MaxValue;

        foreach (var hit in hits)
        {
            if (!hit.CompareTag("Enemy")) continue;
            if (_player != null && hit.transform == _player) continue;

            float d = (hit.transform.position - (Vector3)center).sqrMagnitude;
            if (d < minDist)
            {
                minDist = d;
                nearest = hit.transform;
            }
        }

        return nearest;
    }

    private void OnRoomSwitchStarted(int fromRoomId, int toRoomId)
    {
        // 随从传送由 MapManager.TeleportFollowers 统一处理（在玩家传送到新房间之后）
    }

    private void HandleDeath()
    {
        _isActive = false;
        _isReviving = true;

        // 停止状态机
        _followerSM?.ChangeState(null);

        // 禁用碰撞
        foreach (var col in GetComponentsInChildren<Collider2D>())
            col.enabled = false;

        _movement?.Stop();

        // 隐藏视觉
        foreach (var sr in GetComponentsInChildren<SpriteRenderer>())
            sr.enabled = false;

        StartCoroutine(RespawnRoutine());
    }

    private IEnumerator RespawnRoutine()
    {
        yield return new WaitForSeconds(_respawnDelay);

        // 复活
        if (_core?.Health != null)
        {
            _core.Health.Revive();
            ApplyEvolutionBuff();
        }

        // 传送到玩家身边
        if (_player != null)
            _movement?.Teleport(_player.position);

        // 恢复视觉和碰撞
        foreach (var sr in GetComponentsInChildren<SpriteRenderer>())
            sr.enabled = true;
        foreach (var col in GetComponentsInChildren<Collider2D>())
            col.enabled = true;

        _isActive = true;
        _isReviving = false;

        // 重启状态机
        _followerSM?.ChangeState(new FollowerIdleState(this));
    }

    private void OnSceneLoaded(Scene scene, LoadSceneMode mode)
    {
        if (scene.name == "Start" || scene.name == "Result" || scene.name == "Winning")
        {
            Destroy(gameObject);
            return;
        }

        // 游戏场景：重新查找玩家引用
        if (PlayerManager.Instance != null && PlayerManager.Instance.CurrentPlayer != null)
            _player = PlayerManager.Instance.CurrentPlayer.transform;
        else
            _player = GameObject.FindGameObjectWithTag("Player")?.transform;

        // 传送到玩家身边（防止随从出现在旧位置）
        if (_player != null && _movement != null && !_isReviving)
            _movement.Teleport(_player.position);
    }

    // ── 槽位与升级 ──

    /// <summary>查找最小空闲槽位索引（0..MaxFollowerCount-1），满员返回 MaxFollowerCount</summary>
    private int FindFreeSlotIndex()
    {
        var used = new System.Collections.Generic.HashSet<int>();
        foreach (var f in ActiveFollowers)
        {
            if (f != this && f.SlotIndex >= 0)
                used.Add(f.SlotIndex);
        }

        for (int i = 0; i < MaxFollowerCount; i++)
        {
            if (!used.Contains(i))
                return i;
        }
        return MaxFollowerCount;
    }

    /// <summary>按槽位顺序返回随从列表（空槽为 null，长度 = MaxFollowerCount）</summary>
    public static System.Collections.Generic.List<EnemyFollower> GetSlotsInOrder()
    {
        var list = new System.Collections.Generic.List<EnemyFollower>();
        for (int i = 0; i < MaxFollowerCount; i++)
        {
            EnemyFollower found = null;
            foreach (var f in ActiveFollowers)
            {
                if (f.SlotIndex == i)
                {
                    found = f;
                    break;
                }
            }
            list.Add(found);
        }
        return list;
    }

    /// <summary>判断两个敌人是否同种类（config 引用相等，config 为空回退 displayName）</summary>
    public static bool SameType(EnemyCore a, EnemyCore b)
    {
        if (a == null || b == null) return false;

        var ca = a.config;
        var cb = b.config;
        if (ca != null && cb != null) return ca == cb;

        return string.Equals(ca != null ? ca.displayName : null,
                             cb != null ? cb.displayName : null);
    }

    /// <summary>
    /// 升级随从：等级 +1，属性按 _levelStatFactor 提升，技能等级 +1（可选）。
    /// </summary>
    public void UpgradeLevel()
    {
        Level++;

        if (_upgradeSkillsOnLevelUp && _skillManager != null)
        {
            foreach (var s in _skillManager.SkillInstances)
                s?.TryUpgrade();
        }

        ApplyEvolutionBuff();
        Revision++;
    }

    /// <summary>
    /// 把敌人同化到指定槽位：空槽=放置；同种=升级并消耗敌人；异种=替换（销毁旧随从）。
    /// 成功路径都会触发 OnAssimilated（供房间计数/门锁逻辑）。
    /// </summary>
    public static FollowerSlotResult AssimilateToSlot(EnemyCore enemy, Transform player, int slotIndex)
    {
        if (enemy == null || player == null)
            return FollowerSlotResult.Failed;

        var slots = GetSlotsInOrder();
        if (slotIndex < 0 || slotIndex >= slots.Count)
            return FollowerSlotResult.Failed;

        var existing = slots[slotIndex];

        // 同种升级：提升现有随从等级，消耗被侵蚀的敌人（不创建新随从）
        if (existing != null && SameType(existing.Core, enemy))
        {
            existing.UpgradeLevel();
            enemy.ConsumeAsAssimilated(player);
            return FollowerSlotResult.Upgraded;
        }

        // 替换：同步销毁旧随从释放槽位（时间缩放 0 时 Destroy 延后一帧会导致槽位短暂重复）
        // 注意：DestroyImmediate 后 Unity 对象判空（existing != null）会变为 false，须先缓存布尔值
        bool hadExisting = existing != null;
        if (hadExisting)
            DestroyImmediate(existing.gameObject);

        // 放置/替换：同化敌人到指定槽位
        enemy.Assimilate(player, slotIndex);
        return hadExisting ? FollowerSlotResult.Replaced : FollowerSlotResult.Placed;
    }
}

/// <summary>同化到槽位的操作结果</summary>
public enum FollowerSlotResult
{
    Failed,
    Placed,
    Upgraded,
    Replaced
}

using System;
using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// 统一敌人对外接口，供生成器、技能及其它系统使用。
/// 重构目标是让外部通过接口而非具体 BaseEnemy 类型交互。
/// </summary>
public interface IEnemy : IDamageable, ISkillCaster
{
    /// <summary>用于外部查询或定位的 Transform 引用</summary>
    Transform EnemyTransform { get; }

    /// <summary>敌人是否已死亡</summary>
    bool IsDead { get; }

    /// <summary>是否已被同化为随从（房间/生成器应排除）</summary>
    bool IsAssimilated { get; }

    /// <summary>敌人当前持有的技能实例（只读）</summary>
    IReadOnlyList<SkillInstance> SkillInstances { get; }

    /// <summary>敌人死亡事件（触发时表示该敌人已死亡/即将销毁）</summary>
    event Action OnDied;

    /// <summary>敌人被同化为随从事件（触发时房间/生成器应从存活列表移除）</summary>
    event Action<IEnemy> OnAssimilated;
}

using System;
using UnityEngine;

/// <summary>
/// 敌人统计数据组件 — 所有属性的唯一数据源（类似 PlayerStats）。
/// 血量、移速、感知范围、攻击范围、碰撞伤害等统一在此管理，
/// 提供 GetStatValue / SetStatValue 接口供 Buff 系统读写。
///
/// 数据初始化：EnemyCore 在 Awake 中从 EnemyConfig 赋值，然后调用 Initialize()。
/// </summary>
public class EnemyStats : MonoBehaviour, IDamageable, IHealable
{
    // ════════════════════════════════════════════
    //  生命
    // ════════════════════════════════════════════
    [Header("──── 生命 ────")]
    public float MaxHealth = 30f;
    private float _health;
    private bool _isDead = false;
    private bool _initialized = false;

    // ════════════════════════════════════════════
    //  移动速度
    // ════════════════════════════════════════════
    [Header("──── 移动速度 ────")]
    [Tooltip("巡逻速度")]
    public float PatrolSpeed = 1f;
    [Tooltip("追击速度")]
    public float ChaseSpeed = 2.5f;

    // ════════════════════════════════════════════
    //  感知与攻击
    // ════════════════════════════════════════════
    [Header("──── 感知与攻击 ────")]
    [Tooltip("发现玩家范围")]
    public float DetectionRange = 5f;
    [Tooltip("攻击范围")]
    public float AttackRange = 1.2f;

    // ════════════════════════════════════════════
    //  碰撞伤害
    // ════════════════════════════════════════════
    [Header("──── 碰撞伤害 ────")]
    [Tooltip("接触玩家时造成的伤害")]
    public float ContactDamage = 10f;
    [Tooltip("碰撞伤害冷却（秒）")]
    public float ContactDamageCooldown = 1f;

    // ──────────────────────────────────────────
    //  只读属性
    // ──────────────────────────────────────────
    public bool IsDead => _isDead;
    public float CurrentHealth => _health;

    // ──────────────────────────────────────────
    //  事件
    // ──────────────────────────────────────────
    public event Action<float, float> OnHealthChanged;
    public event Action OnDied;
    public event Action<float> OnDamaged;
    /// <summary>属性变化事件：参数为 (属性名)</summary>
    public event Action<string> OnStatChanged;

    /// <summary>技能命中附带目标当前生命的百分比伤害（蛋白激酶），0=关闭</summary>
    public static float OnSkillHitPercentDamage = 0f;

    // ──────────────────────────────────────────
    //  初始化
    // ──────────────────────────────────────────

    /// <summary>
    /// 由 EnemyCore 在设置各项属性后调用。
    /// 确保 _health 从最终 MaxHealth 初始化。
    /// </summary>
    public void Initialize()
    {
        if (_initialized) return;
        _health = MaxHealth;
        _initialized = true;
    }

    // ──────────────────────────────────────────
    //  IDamageable
    // ──────────────────────────────────────────

    public void TakeDamage(float damage)
    {
        if (_isDead) return;

        var immunity = GetComponent<DamageImmunity>();
        if (immunity != null && immunity.IsImmune) return;

        // 受击闪避（肌纤维应激细胞等）：成功闪避则免疫本次伤害并滑移
        var dodge = GetComponent<DodgeComponent>();
        if (dodge != null)
        {
            // 闪避方向：远离最近的敌人（通常是玩家/攻击者方向的反向）
            Vector2 hitDir = Vector2.right;
            var player = PlayerManager.Instance != null ? PlayerManager.Instance.CurrentPlayer : null;
            if (player != null)
                hitDir = ((Vector2)transform.position - (Vector2)player.transform.position).normalized;
            if (hitDir.sqrMagnitude < 0.01f)
                hitDir = Vector2.right;

            if (dodge.TryDodge(hitDir))
                return;  // 闪避成功，免疫本次伤害
        }

        // 伤害吸收护盾（角质增厚细胞等）：先免伤再吸收
        var absorbShield = GetComponent<AbsorbShield>();
        if (absorbShield != null && absorbShield.IsActive)
            absorbShield.TryAbsorb(ref damage);

        if (damage <= 0f) return;

        var analgesic = GetComponent<AnalgesicBlockRuntime>();
        if (analgesic != null && analgesic.IsActive)
            damage = analgesic.SplitDamage(damage);

        // 蛋白激酶：技能命中附带目标当前生命百分比伤害
        if (SkillInstance.SkillDamageActive && OnSkillHitPercentDamage > 0f)
            damage += _health * OnSkillHitPercentDamage;

        _health -= damage;
        _health = Mathf.Max(_health, 0f);

        DamagePopup.Spawn(transform.position, damage);

        // 受击音效（0.05s 最小间隔由 AudioManager 内部控制，防高频叠加）
        if (AudioManager.Instance != null)
            AudioManager.Instance.PlaySFX("enemy_hurt");

        if (CameraShake.Instance != null)
            CameraShake.Instance.Shake(0.7f);

        OnDamaged?.Invoke(damage);
        OnHealthChanged?.Invoke(_health, MaxHealth);

        if (_health <= 0f)
            Die();
    }

    // ──────────────────────────────────────────
    //  IHealable
    // ──────────────────────────────────────────

    public void Heal(float amount)
    {
        if (_isDead) return;
        _health = Mathf.Min(_health + amount, MaxHealth);
        OnHealthChanged?.Invoke(_health, MaxHealth);
    }

    private void Die()
    {
        if (_isDead) return;
        _isDead = true;
        OnDied?.Invoke();
    }

    /// <summary>清除 OnDied 事件的所有订阅者（同化时切换死亡处理）。</summary>
    public void ClearOnDied()
    {
        OnDied = null;
    }

    /// <summary>复活：重置死亡状态并回满血。</summary>
    public void Revive()
    {
        _isDead = false;
        _health = MaxHealth;
        OnHealthChanged?.Invoke(_health, MaxHealth);
    }

    // ──────────────────────────────────────────
    //  Buff 系统属性读写接口（类同 PlayerStats）
    // ──────────────────────────────────────────

    public float GetStatValue(string statName)
    {
        return statName switch
        {
            "MaxHealth"             => MaxHealth,
            "Health"                => _health,
            "PatrolSpeed"           => PatrolSpeed,
            "ChaseSpeed"            => ChaseSpeed,
            "DetectionRange"        => DetectionRange,
            "AttackRange"           => AttackRange,
            "ContactDamage"         => ContactDamage,
            "ContactDamageCooldown" => ContactDamageCooldown,
            _ => throw new ArgumentException($"EnemyStats: 未知属性名 '{statName}'")
        };
    }

    public void SetStatValue(string statName, float value)
    {
        switch (statName)
        {
            case "MaxHealth":
                MaxHealth = Mathf.Max(value, 1f);
                _health = Mathf.Min(_health, MaxHealth);
                break;
            case "Health":
                _health = Mathf.Clamp(value, 0f, MaxHealth);
                break;
            case "PatrolSpeed":
                PatrolSpeed = Mathf.Max(value, 0f);
                break;
            case "ChaseSpeed":
                ChaseSpeed = Mathf.Max(value, 0f);
                break;
            case "DetectionRange":
                DetectionRange = Mathf.Max(value, 0f);
                break;
            case "AttackRange":
                AttackRange = Mathf.Max(value, 0f);
                break;
            case "ContactDamage":
                ContactDamage = Mathf.Max(value, 0f);
                break;
            case "ContactDamageCooldown":
                ContactDamageCooldown = Mathf.Max(value, 0f);
                break;
            default:
                throw new ArgumentException($"EnemyStats: 未知属性名 '{statName}'");
        }
        OnStatChanged?.Invoke(statName);
    }
}

using UnityEngine;

/// <summary>
/// 敌人死亡生成器 — 全局自动注册，监听所有敌人死亡事件。
/// 根据配置（EnemyDeathSpawnConfig）在死亡位置按概率生成额外单位（如噬菌体、分裂怪等）。
/// 支持多组生成条目，每组可指定概率、排除列表、是否排除 Boss。
/// 配置通过 Resources/EnemyDeathSpawnConfig.asset 加载。
/// </summary>
public class EnemyDeathSpawner : MonoBehaviour
{
    private static EnemyDeathSpawner _instance;

    [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]
    private static void Init()
    {
        if (_instance == null)
        {
            var go = new GameObject(nameof(EnemyDeathSpawner));
            _instance = go.AddComponent<EnemyDeathSpawner>();
            DontDestroyOnLoad(go);
        }
    }

    private EnemyDeathSpawnConfig _config;

    private void OnEnable()
    {
        EnemyCore.OnAnyEnemyDied += OnEnemyDied;

        _config = Resources.Load<EnemyDeathSpawnConfig>("EnemyDeathSpawnConfig");
        if (_config == null)
            Debug.LogWarning("[EnemyDeathSpawner] 未找到 EnemyDeathSpawnConfig.asset，死亡生成功能禁用");
    }

    private void OnDisable()
    {
        EnemyCore.OnAnyEnemyDied -= OnEnemyDied;
    }

    private void OnEnemyDied(EnemyCore enemy)
    {
        if (_config == null || _config.entries == null) return;

        string enemyName = enemy.config != null ? enemy.config.displayName : "";
        bool isBoss = enemy.GetComponent<BossCore>() != null;

        foreach (var entry in _config.entries)
        {
            if (entry == null || entry.prefab == null) continue;

            // 排除 Boss
            if (entry.excludeBoss && isBoss) continue;

            // 排除指定名称（防自身繁殖等）
            if (entry.excludeNames != null && entry.excludeNames.Contains(enemyName)) continue;

            // 概率判定
            if (Random.value > entry.spawnChance) continue;

            // 生成位置（带散布偏移）
            Vector2 pos = enemy.transform.position;
            if (entry.spawnRadius > 0f)
                pos += Random.insideUnitCircle * entry.spawnRadius;

            var go = Instantiate(entry.prefab, pos, Quaternion.identity);
            go.name = $"DeathSpawn_{entry.prefab.name}";

            Debug.Log($"[EnemyDeathSpawner] {enemyName} 死亡 → 生成 {entry.prefab.name}");
        }
    }
}

